# =====================================================================  MAKE
def make(C):
    deep = {
     0: r"""<h3>Make vocabulary</h3>""" + tb(["Term", "Meaning"], [["Scenario", "One automation, drawn as connected modules on a canvas"], ["Module", "One step (trigger, action, search, tool)"], ["Bundle", "One item of data passing through the scenario"], ["Operation", "One module run on one bundle; the usual billing unit (check current plan)"], ["Connection", "A saved login to an app"], ["Webhook", "A URL that starts the scenario when called"], ["Data store", "Simple built-in table to keep state between runs"], ["Scheduling", "Run on demand, at intervals, or instantly via webhook"], ["Execution history", "Log of runs with data in and out"], ["Blueprint", "Export of a scenario as a file for backup or sharing"]]) + NOTE,
     2: r"""<h3>Iterator and aggregator in a picture</h3>""" + ill_flow(["Order with 3 products (one bundle)", "Iterator: 3 bundles, one per product", "Process each product (look up stock)", "Aggregator: combine into one summary", "Send one message"], "Split a list, work on each item, then join the results") + r"""<p>Use <b>Iterator</b> to split an array into items; use an <b>Aggregator</b> (array, text, numeric, table) to join results back into one bundle. Without an aggregator, later modules run once per item.</p>""",
     3: r"""<h3>JSON basics for automation builders</h3><pre>{
  "order_id": "A-1001",
  "customer": {"name": "Ravi", "phone": "9876543210"},
  "items": [{"sku": "S1", "qty": 2}, {"sku": "S2", "qty": 1}],
  "total": 1499
}</pre><ul><li>Curly braces hold named fields; square brackets hold lists.</li><li>Use <b>Parse JSON</b> with a data structure so fields appear as mappable items.</li><li>For HTTP calls: set method, URL, headers (Authorization), query or body, and parse the response.</li></ul>""",
     4: r"""<h3>Error handling directives</h3>""" + tb(["Directive", "What it does", "Use for"], [["Ignore", "Skip the failed bundle and continue", "Non-critical steps"], ["Resume", "Substitute a default value and continue", "Optional data"], ["Commit", "Stop and keep what was already done", "Partial success is acceptable"], ["Rollback", "Stop and undo changes where the apps support it", "Transactions that must be all-or-nothing"], ["Break", "Store as an incomplete execution to retry later", "Temporary failures like rate limits"]]),
    }
    new = [
     ("basic", "Make interface tour and your first canvas habits", "Get comfortable with the editor and good building habits.", r"""
<ul><li><b>Canvas:</b> drag modules, connect with lines, right-click for options; use <b>Run once</b> to test with live data and see bundles at every module.</li><li><b>Scenario settings:</b> schedule, sequential processing, data is confidential, max cycles, auto-commit.</li><li><b>Mapping panel:</b> click a field to insert data from earlier modules; use functions (formatDate, replace, substring, if, ifempty) for transformations.</li><li><b>Naming and notes:</b> rename modules ('Find customer by email') and add notes; future you will be grateful.</li><li><b>Folders, teams and organisations:</b> keep scenarios organised and share with teammates.</li><li><b>Templates:</b> start from a template, then change the connections and test.</li></ul>""" + tb(["Habit", "Why"], [["Test each module as you add it", "Find mapping errors early"], ["Use filters between modules", "Stop unwanted bundles and save operations"], ["Build small, then expand", "Easier to debug"], ["Export a blueprint before big changes", "Safe backup"], ["Add an error route", "No silent failures"]]),
      ["Run once to inspect data at each step.", "Name modules clearly.", "Back up with a blueprint."], "Open a template, run it once, and write down what data each module outputs."),
     ("intermediate", "Mapping data: functions, dates, text, arrays and JSON", "Transform data without code.", tb(["Task", "Function / module", "Example"], [["Join first and last name", "Text: concatenation or a variable", "Ravi + Kumar = Ravi Kumar"], ["Replace text", "replace(text; old; new)", "Remove spaces from a phone number"], ["Format date", "formatDate(date; format; timezone)", "04 Nov 2026 10:30 in Asia/Kolkata"], ["Add days", "addDays(date; n)", "Follow-up date"], ["Default value", "ifempty(value; default)", "Use 'Unknown' when blank"], ["Conditional text", "if(condition; a; b)", "Hot if budget > 50,000 else Warm"], ["Get item from array", "get(array; index) or first()", "First product name"], ["Sum numbers", "sum(array)", "Order total"], ["Create JSON", "Create JSON / JSON module", "Payload to send to another API"], ["Regex", "Text parser: match pattern", "Extract order number from text"]]) + r"""
<p><b>Tips:</b> watch data types (text vs number vs date), time zones, and array positions (Make arrays start at 1).</p>""",
      ["Know your types: text, number, date, array.", "Use ifempty and if to avoid blanks and errors.", "Convert time zones deliberately."], "Write the mapping expressions to build a clean customer record from a messy form entry."),
     ("intermediate", "Real workflows by role", "Copy practical scenarios and adapt them.", tb(["Role", "Scenario", "Modules in order"], [
        ["Product manager", "Feedback to backlog", "Watch rows (Sheet) → HTTP or AI module to classify → Notion/Jira create item → Slack message"],
        ["Marketing", "Lead capture and nurture", "Webhook (form) → Router (hot/cold) → CRM create → email sequence start → data store log"],
        ["Support", "Ticket categorisation", "Watch emails → AI categorise → Router → helpdesk create ticket → acknowledgement email"],
        ["Finance", "Invoice to sheet", "Watch email attachments → OCR or AI extract → Sheet add row → Slack approval message"],
        ["E-commerce", "Order and inventory sync", "Webhook (new order) → Iterator (line items) → update stock sheet → aggregator → confirmation message"],
        ["Operations", "Daily report", "Schedule 8 am → fetch data (HTTP) → aggregate → build HTML → email"],
        ["HR", "Onboarding", "Watch new employee row → create accounts via HTTP → send checklist → calendar invites"]]) + r"""
<p>Start with the simplest version, add routers for exceptions and error handlers last.</p>""",
      ["Pick workflows with clear triggers.", "Add routers for exceptions.", "Document each scenario."], "Choose one scenario and draw its module map with error routes."),
     ("intermediate", "HTTP, APIs, authentication and pagination", "Connect to any service, even without a ready-made app.", ill_flow(["Read the API docs", "Get a key or OAuth token", "Test in a REST client", "Make an HTTP module call", "Parse JSON response", "Handle errors and pagination"], "Connecting to a custom API") + r"""
<ul><li><b>Authentication:</b> API key in a header, bearer token, basic auth, or OAuth 2.0 (use Make's connection support). Store secrets in connections or scenario variables, never in plain notes.</li><li><b>Pagination:</b> many APIs return pages; loop with a repeater or 'next page' token until done.</li><li><b>Rate limits:</b> add sleep modules or use sequential processing; respect HTTP 429 responses.</li><li><b>Webhook security:</b> add a secret in the URL or header and check it in a filter.</li><li><b>Idempotency:</b> include unique IDs to prevent duplicate orders or payments if a run is retried.</li></ul>""" + tb(["HTTP status", "Meaning", "Action"], [["200 / 201", "Success / created", "Continue"], ["400", "Bad request", "Fix payload"], ["401 / 403", "Not allowed", "Check key or scope"], ["404", "Not found", "Check ID or URL"], ["429", "Too many requests", "Wait and retry"], ["500+", "Server error", "Retry later; alert if repeated"]]),
      ["Use connections for secrets.", "Handle pagination and rate limits.", "Include unique IDs to avoid duplicates."], "Call a public API (for example a weather or currency API) from Make and save results to a sheet."),
     ("advanced", "Reliability: error routes, retries, data stores and locking", "Make scenarios resilient.", tb(["Problem", "Design"], [["Temporary outage", "Break directive with automatic retries; alert if retries exhausted"], ["Bad data in one bundle", "Error route that logs the bundle to a sheet and notifies the owner; continue others"], ["Duplicate runs", "Store processed IDs in a data store and skip if seen"], ["Order of processing matters", "Enable sequential processing; use queues"], ["Two scenarios editing the same record", "Use a lock flag in a data store or process via one scenario"], ["Large volumes", "Process in batches; schedule off-peak; split scenarios"], ["Monitoring", "Email or Slack alerts on error, daily summary of runs and failures"]]) + r"""
<h3>Incomplete executions</h3><p>When Break is used, failed runs wait in <b>Incomplete executions</b>. Review daily, fix the cause, and run them again.</p>""",
      ["Create an error route for every important scenario.", "Use data stores to remember what is done.", "Review incomplete executions regularly."], "Add error handling and duplicate protection to a scenario that creates CRM contacts."),
     ("advanced", "AI in Make, agents and responsible use", "Add AI steps with control.", r"""
<ul><li><b>AI modules:</b> classify, extract, summarise, translate and draft using providers such as OpenAI, Anthropic and Gemini through ready modules or HTTP calls; Make also offers its own AI features and agent-style tools (confirm current names in the docs).</li><li><b>Pattern:</b> collect input → AI with structured JSON output → parse → validate (router with filters) → act or send to human → log.</li><li><b>Cost:</b> each AI call adds provider tokens and one or more operations; monitor both.</li><li><b>Safety:</b> avoid sending sensitive data unless allowed; ask AI to return 'unknown' when unsure; require human approval for customer-facing or money-related actions.</li><li><b>Prompt versions:</b> keep prompts in a data store or note with a version and test cases.</li></ul>""" + tb(["Use case", "Prompt output", "Validation"], [["Lead scoring", "{score: 1-10, reason}", "Score is a number 1-10"], ["Invoice extraction", "{vendor, date, amount, tax}", "Amount > 0, date valid, totals match"], ["Feedback tagging", "{topic, sentiment}", "Topic in allowed list"]]),
      ["Ask for JSON and validate it.", "Monitor provider cost and operations.", "Human approval for risky actions."], "Design the router and validation logic for an AI invoice-extraction scenario."),
     ("advanced", "Cost control, governance and choosing Make vs Zapier vs n8n", "Run automations at scale and pick the right tool.", tb(["Lever", "How it reduces operations"], [["Filter early", "Stop unwanted bundles before costly modules"], ["Aggregate", "Send one message or API call instead of many"], ["Use schedules", "Poll less often when real-time is not needed"], ["Webhooks over polling", "Instant and cheaper than frequent polling"], ["Avoid unnecessary searches", "Pass IDs instead of searching again"], ["Clean up", "Turn off test scenarios; review top consumers monthly"]]) + r"""
<h3>Governance</h3><ul><li>Use an organisation account with roles; avoid personal connections.</li><li>Keep an inventory: purpose, owner, data used, apps, last review.</li><li>Peer review changes to critical scenarios; export blueprints as backups.</li><li>Define who gets alerts and who fixes.</li></ul>""" + tb(["Choose", "When"], [["Make", "Visual, data-heavy workflows with routers, iterators and detailed control"], ["Zapier", "Fast simple automations and the widest app coverage"], ["n8n", "Technical teams, self-hosting, privacy, custom code and scale"], ["Code", "Core product logic and heavy workloads"]]),
      ["Filter, aggregate and schedule wisely.", "Inventory and review automations.", "Pick the tool by logic complexity and data sensitivity."], "Estimate operations for your top scenarios and choose two cost-saving changes."),
     ("advanced", "Three complete scenarios, step by step", "Reproduce detailed builds.", r"""
<h3>Scenario 1: Webhook lead intake with scoring</h3><ol><li>Custom webhook receives form data.</li><li>Set variables: clean phone, name, normalised email.</li><li>Search CRM by email; router: update or create.</li><li>AI module scores 1 to 10 with reason (JSON); parse JSON.</li><li>Router: score ≥ 8 → Slack alert + task for sales; else → add to nurture sequence.</li><li>Data store: save lead ID to prevent duplicates; error route emails the owner.</li></ol>
<h3>Scenario 2: Order with many items to inventory and confirmation</h3><ol><li>Webhook receives order JSON; parse JSON.</li><li>Iterator over items; for each, update stock in sheet or database.</li><li>Aggregator builds a summary text; send confirmation by email or WhatsApp.</li><li>Router: if any item below threshold → alert the purchasing channel.</li><li>Error handler: commit what succeeded and log failures to a sheet.</li></ol>
<h3>Scenario 3: Daily operations digest</h3><ol><li>Scheduler at 8:00 on weekdays.</li><li>HTTP modules fetch orders, tickets and failures (with pagination).</li><li>Aggregate counts and top issues; AI writes a 5-line summary.</li><li>Build an HTML email with a table; send to the leadership list; archive in Drive.</li></ol>""",
      ["Parse, validate, route, act, log.", "Protect against duplicates and failures.", "Summaries help humans stay in control."], "Build one scenario with test data and run it 10 times, including a failure case."),
    ]
    qa = [("What is the difference between an operation and a bundle in Make?", "A bundle is one item of data; an operation is one module processing one bundle. Operations are typically what counts toward the plan (check current rules)."),
          ("When do you use an iterator and an aggregator?", "Use an iterator to split an array into individual items and an aggregator to combine results back into a single bundle."),
          ("How do you handle errors in Make?", "Add error routes with directives: ignore, resume, commit, rollback or break, and review incomplete executions; alert owners."),
          ("How do you prevent duplicate processing?", "Store processed IDs in a data store, search before creating, and use idempotency keys when calling APIs."),
          ("How would you connect an app with no module?", "Use the HTTP module with the API's authentication, parse the JSON response, and handle pagination and rate limits."),
          ("How do you secure webhooks?", "Use a secret in the URL or header, validate it, restrict logging of sensitive data, and rotate if exposed."),
          ("How do you reduce operations usage?", "Filter early, aggregate, use webhooks instead of polling, schedule wisely and remove unused scenarios."),
          ("Make or Zapier?", "Make for visual, data-heavy, multi-branch scenarios; Zapier for fast simple automations and the largest app library; choose after testing a real workflow in each.")]
    gl = [("Router", "Splits flow into multiple routes with filters"), ("Iterator", "Splits an array into individual bundles"), ("Aggregator", "Combines bundles into one"), ("Data store", "Built-in key-value table"), ("Incomplete execution", "A run saved for retry after a Break"),
          ("Blueprint", "Exported scenario file"), ("Sequential processing", "Process bundles one at a time in order"), ("Repeater", "Generates a series of bundles, useful for pagination"), ("Parse JSON", "Turn JSON text into mappable fields")]
    cheat = [("Split and join", "Iterator then aggregator"), ("Error plan", "Route, directive, alert, review incomplete runs"), ("Cost rule", "Filter, aggregate, webhook, schedule"), ("AI rule", "JSON out, validate, human for risky")]
    return extend(C, deep, new, qa, gl, cheat, links=[("Make: functions reference", "https://help.make.com/"), ("Make: error handling", "https://help.make.com/")])
